mapper.select:
SELECT u.user_id, u.nick_name AS nickname, AS phone_masked, COALESCE(uac.enabled, 0) AS enabled, uac.reason, op.nick_name AS operator_name, uac.operated_at AS updated_at FROM sys_user u LEFT JOIN user_author_capability uac ON uac.user_id = u.user_id LEFT JOIN sys_user op ON op.user_id = uac.operator_id WHERE u.user_type IN ('01', '02', '03') AND u.del_flag = '0'
AND ( u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%') )
AND COALESCE(uac.enabled, 0) = #{enabled}
ORDER BY ${orderByColumn} ${isAsc}
